create temp table test_results(name text primary key,passed boolean not null);
grant select,insert on test_results to authenticated,anon;
create function pg_temp.assert_true(value boolean,name text) returns void language plpgsql set search_path='' as $$ begin if value is distinct from true then raise exception 'FAILED: %',name; end if; insert into pg_temp.test_results values(name,true); end $$;
create function pg_temp.expect_error(statement text,state text,name text) returns void language plpgsql set search_path='' as $$ declare caught text; begin begin execute statement; exception when others then get stacked diagnostics caught=returned_sqlstate; end; if caught is distinct from state then raise exception 'FAILED: %, expected %, got %',name,state,caught; end if; insert into pg_temp.test_results values(name,true); end $$;
